        }
        for (let i = 0; i < scwin.stockDutyarr.length; i++) {
            let totalShrs = scwin.stockDutyarr[i].stkoptDutyTotGrntShrs;
            for (let c = 0; c <= scwin.stockDutyarr[i].rowcnt; c++) {
                const iIndex = scwin.stockDutyarr[i].bzProcsNo + "" + scwin.stockDutyarr[i].prtdepoId + "" + scwin.stockDutyarr[i].rowcnt + "" + c;
                for (let j = 0; j < scwin.stockDutyExerarr.length; j++) {
                    const jIndex = scwin.stockDutyExerarr[j].bzProcsNo + "" + scwin.stockDutyExerarr[j].prtdepoId + "" + scwin.stockDutyExerarr[j].rowcnt + "" + scwin.stockDutyExerarr[j].roid;
                    if (iIndex === jIndex) {
                        if (scwin.stockDutyExerarr[j].listProcsStatCd !== "37") {
                            totalShrs = totalShrs - scwin.stockDutyExerarr[j].stkoptDutyExerShrs;
                        }
                        const intoId = scwin.stockDutyarr[i].bzProcsNo + "" + scwin.stockDutyarr[i].prtdepoId + "" + scwin.stockDutyarr[i].rowcnt + "" + c;
                        $("#" + intoId).html($c.num.formatNumber(totalShrs));
                    }
                }
            }
        }

