// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_stockDutyExerSubmit, tx_fn_openAdjReqWin) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.stockDutyarr =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05104' }); }

try { scwin.stockDutyExerarr =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05104' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05104.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_stockDutyExerList_oncellclick
 * @description grd_stockDutyExerList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_stockDutyExerList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_stockDutyExerList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_stockDutyExerList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if ((r["listProcsStatCd"] === '' || r["listProcsStatCd"] === '30')) { await scwin.openStockDutyExerWin(r["bzProcsNo"], r["follwBzProcsNo"], r["listProcsStatCd"]); return; }
        if (r["listProcsStatCd"] === '35') { await scwin.openStockDutyExerWin(r["bzProcsNo"], r["follwBzProcsNo"], r["listProcsStatCd"]); return; }
        if (r["listProcsStatCd"] === '37') { await scwin.openStockDutyExerWin(r["bzProcsNo"], r["follwBzProcsNo"], r["listProcsStatCd"]); return; }
        if (r["listProcsStatCd"] === '' || r["listProcsStatCd"] === '30' ||r["listProcsStatCd"] === '35' ||r["listProcsStatCd"] === '37') { await scwin.stockDutyExerSubmit(r["follwBzProcsNo"], r["prtdepoId"], "32"); return; }
        if (r["listProcsStatCd"] === '33') { await scwin.openAdjReqWin(r["follwBzProcsNo"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_stockDutyExerList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_openStockDutyExerWin_7_onclick
 * @description 「신규작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_openStockDutyExerWin_7_onclick = async function(e){
    try {
        await scwin.openStockDutyExerWin('','','')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05104.btn_openStockDutyExerWin_7_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_stockDutyExerSubmit
 * @description stock Duty Exer Submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_stockDutyExerSubmit = async function () {
    const sbmOptions = {
        id: "tx_fn_stockDutyExerSubmit",
        method: "post",
        action: "/list/listDisclosureForm.do",
        ref: "dma_stockDutyExerSubmitReq",
        target: "dlt_stockDutyExerList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_openAdjReqWin
 * @description open Adj Req Win 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openAdjReqWin = async function () {
    const sbmOptions = {
        id: "tx_fn_openAdjReqWin",
        method: "post",
        action: "/list/searchNewListInvstgMaster.do",
        ref: "dma_openAdjReqWinReq",
        target: "dlt_stockDutyExerList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openStockDutyExerWin
 * @description open Stock Duty Exer Win 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} follwBzProcsNo follwBzProcsNo
 * @param {String} listProcsStatCd listProcsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openStockDutyExerWin = async function (bzProcsNo, follwBzProcsNo, listProcsStatCd) {
    if (scwin.stockDutyExerarr.length === 0) {
        await $c.win.alert("종류주식 신규/우회/스팩존속합병을 등록해 주세요");
        return;
    }
    const stockDutyExerWin = {};
    stockDutyExerWin.calcelYn = 'Y';
    const url = "/jldfil05106/jldfil05106.xml?method=selectStockDutyExer&isurCd=" + "${session.company.isurCd }&bzProcsNo=" + bzProcsNo + "&follwBzProcsNo=" + follwBzProcsNo + "&listProcsStatCd=" + listProcsStatCd;
    const style = "dialogWidth:730px;dialogHeight:580px;scroll:no;resize:no";
    Object.assign(stockDutyExerWin, (await $c.win.openPopup(url, { type: 'pageFramePopup', modal: true }, stockDutyExerWin)) || {});
    if (stockDutyExerWin.calcelYn === 'N') {
        $c.win.setPageFrameSrc($c.win.getFrame(), null);
    }
};

/**
 * @method
 * @name stockDutyExerSubmit
 * @description stock Duty Exer Submit 처리
 * @param {*} follwBzProcsNo follwBzProcsNo
 * @param {String} prtdepoId prtdepoId
 * @param {*} updateType updateType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.stockDutyExerSubmit = async function (follwBzProcsNo, prtdepoId, updateType) {
    scwin.form = (document.stockDutyExerSubForm || { elements: [] });
    const rse = await $c.win.confirm("제출 하시겠습니까? ");
    if (rse) {
        $c.util.getComponent('dma_stockDutyExerSubmitReq').set('follwBzProcsNo', follwBzProcsNo);
        $c.util.getComponent('dma_stockDutyExerSubmitReq').set('prtdepoId', prtdepoId);
        $c.util.getComponent('dma_stockDutyExerSubmitReq').set('listProcsStatCd', updateType);
        scwin.form.action = '/list/listDisclosureForm.do';
        $c.util.getComponent("dma_stockDutyExerSubmitReq").set("method", 'stockDutyExerSubmit');
        await scwin.tx_fn_stockDutyExerSubmit();
    }
};

/**
